// ===================================================
// STEP 1: NORMALIZE & TRUST LAYER
// ===================================================

// ----------------------------
// Helpers
// ----------------------------
// ----------------------------
// BRAND MASTER MAP (Single Source of Truth)
// ----------------------------
const BRAND_MAP = [
  { brand: '5BB', url: 'facebook.com/5BBbroadband' },
  { brand: 'ATOM', url: 'facebook.com/ATOMOfficialPage' },
  { brand: 'Fortune Broadband', url: 'facebook.com/fortunebb' },
  { brand: 'Frontiir', url: 'facebook.com/FrontiirCorporation' },
  { brand: 'Hi Internet', url: 'facebook.com/Hiinternet4u' },
  { brand: 'Kinetic', url: 'facebook.com/share' },
  { brand: 'Mahar Net', url: 'facebook.com/maharnetisp' },
  { brand: 'Marga Global Telecom', url: 'facebook.com/margaglobaltelecommyanmar' },
  { brand: 'MaxxB', url: 'facebook.com/maxxfiberinternet' },
  { brand: 'MBT', url: 'facebook.com/mbt.mm' },
  { brand: 'MIH', url: 'facebook.com/mihconnects' },
  { brand: 'Mojoe Net', url: 'facebook.com/p/MojoeNet' },
  { brand: 'MPT', url: 'facebook.com/mptofficialpage' },
  { brand: 'Myanmar Net', url: 'facebook.com/myanmarnetinternet' },
  { brand: 'Myanmar Speed Net', url: 'facebook.com/myanmarspeednet' },
  { brand: 'Stream Net', url: 'facebook.com/streamnetygn' },
  { brand: 'TrueNet', url: 'facebook.com/truenetwisp' },
  { brand: 'U9', url: 'facebook.com/U9official' },
  { brand: 'Unilink', url: 'facebook.com/Unilinkofficial' },
  { brand: 'Welink', url: 'facebook.com/WeLinkFiber' },
  { brand: 'Yatanarpon', url: 'facebook.com/ytpmn' },
  { brand: 'AGB Communication', url: 'facebook.com/AGB.Communication.Co.Ltd' },
  { brand: 'Novalink', url: 'facebook.com/novalinkmyanmar' },
];


function toNumber(v) {
  const n = Number(v);
  return isNaN(n) ? 0 : n;
}

function resolveBrandName(postUrl) {
  if (!postUrl) return null;

  const cleanUrl = postUrl.toLowerCase();

  const match = BRAND_MAP.find(b =>
    cleanUrl.includes(b.url.toLowerCase())
  );

  return match ? match.brand : null;
}

function cleanPageName(name, url) {
  if (name && name.length > 3) return name.trim();
  if (url) {
    return url
      .replace('https://www.facebook.com/', '')
      .replace('http://www.facebook.com/', '')
      .replace('/', '')
      .trim();
  }
  return null;
}

function formatMyanmarDate(timeValue) {
  if (!timeValue) return null;
  const d = new Date(timeValue);
  if (isNaN(d)) return null;

  const date = new Intl.DateTimeFormat('en-GB', {
    timeZone: 'Asia/Yangon',
    day: '2-digit',
    month: 'short',
    year: 'numeric',
  }).format(d);

  const time = new Intl.DateTimeFormat('en-US', {
    timeZone: 'Asia/Yangon',
    hour: '2-digit',
    minute: '2-digit',
    hour12: true,
  }).format(d);

  return `${date}, ${time}`;
}

function timeBucket(hour) {
  if (hour >= 6 && hour < 10) return 'Morning (6–10 AM)';
  if (hour >= 10 && hour < 14) return 'Midday (10 AM–2 PM)';
  if (hour >= 14 && hour < 18) return 'Afternoon (2–6 PM)';
  if (hour >= 18 && hour < 22) return 'Evening (6–10 PM)';
  return 'Late Night (10 PM–6 AM)';
}

function dayTypeFromTimestamp(ts) {
  const day = new Date(ts).getDay();
  return (day === 0 || day === 6) ? 'Weekend' : 'Weekday';
}

// ----------------------------
// Collect & normalize posts
// ----------------------------
const items = $input.all();
let posts = [];

for (const item of items) {
  const data = Array.isArray(item.json?.data) ? item.json.data : [];

  for (const post of data) {
    try {
      // ---- Page name (trust critical)
      const page = resolveBrandName(post.url);

      // Drop unknown brands
      if (!page) continue;

      // Drop unknown / dirty pages
      if (!page) continue;

      // ---- Metrics
      const reactions = toNumber(post.likes);
      const comments = toNumber(post.comments);
      const shares = toNumber(post.shares);

      const engagement = reactions + comments + shares; // NEVER N/A

      // ---- Time
      if (!post.time) continue;
      const dateObj = new Date(post.time);
      if (isNaN(dateObj)) continue;

      const hour = dateObj.getHours();
      const bucket = timeBucket(hour);
      const dayType = dayTypeFromTimestamp(dateObj.getTime());

      // ---- Post type
      let type = 'Text';
      if (post.isVideo) type = 'Video';
      else if (Array.isArray(post.media) && post.media.length > 0)
        type = 'Image';

      // ---- Reach logic (NO confusing N/A)
      let reach = '–';
      if (post.isVideo) {
        reach = post.viewsCount
          ? toNumber(post.viewsCount)
          : 'Video (no data)';
      }

      // ---- Content snippet
      let content = post.text || '-';
      if (content.length > 250) content = content.slice(0, 250) + '...';

     posts.push({
        page,
        type,
        content,
        reactions,
        comments,
        shares,
        engagement,
        reach,
        postedAt: formatMyanmarDate(post.time),
        timestamp: dateObj.getTime(),
        hour,
        timeBucket: bucket,
        dayType,                 // 👈 ADD THIS
        link: post.url || '#',
      });
    } catch (e) {
      continue;
    }
  }
}

// ----------------------------
// Aggregations (used by CEO & Analyst)
// ----------------------------

// Page-level summary
// ----------------------------
// Page-level summary (FINAL)
// ----------------------------
const pageSummary = {};
for (const p of posts) {
  if (!pageSummary[p.page]) {
    pageSummary[p.page] = {
      page: p.page,
      posts: 0,
      reactions: 0,
      comments: 0,
      shares: 0,
      engagement: 0,
    };
  }

  pageSummary[p.page].posts += 1;
  pageSummary[p.page].reactions += p.reactions;
  pageSummary[p.page].comments += p.comments;
  pageSummary[p.page].shares += p.shares;
  pageSummary[p.page].engagement += p.engagement;
}

// Time bucket summary
const timeSummary = {};
for (const p of posts) {
  const key = `${p.dayType} | ${p.timeBucket}`;

  if (!timeSummary[key]) {
    timeSummary[key] = {
      label: key,
      posts: 0,
      engagement: 0,
    };
  }

  timeSummary[key].posts++;
  timeSummary[key].engagement += p.engagement;
}

// Type summary
const typeSummary = {};
for (const p of posts) {
  if (!typeSummary[p.type]) {
    typeSummary[p.type] = {
      type: p.type,
      posts: 0,
      engagement: 0,
    };
  }
  typeSummary[p.type].posts++;
  typeSummary[p.type].engagement += p.engagement;
}

// ----------------------------
// Sort summaries
// ----------------------------
const pages = Object.values(pageSummary).sort(
  (a, b) => b.engagement - a.engagement
);

const times = Object.values(timeSummary).sort(
  (a, b) => b.engagement - a.engagement
);

const types = Object.values(typeSummary).sort(
  (a, b) => b.engagement - a.engagement
);

// ----------------------------
// Output (Single Source of Truth)
// ----------------------------
return [
  {
    json: {
      meta: {
        totalPosts: posts.length,
        generatedAt: new Date().toISOString(),
        timezone: 'Asia/Yangon',
        engagementFormula: 'Reactions + Comments + Shares',
        reachNote: 'Reach is available only for video posts',
      },
      posts,        // Used by Analyst view
      pages,        // Used by CEO ranking
      times,        // Used by best posting window
      types,        // Used by content strategy
    },
  },
];

// ===================================================
// STEP 2: COMBINED CEO + ANALYST EMAIL (ENHANCED)
// ===================================================

// ---------- Helpers ----------
function formatBrandName(name) {
  if (!name) return '-';
  return name
    .replace(/([a-z])([A-Z])/g, '$1 $2')       // camelCase → space
    .replace(/official/gi, 'Official')
    .replace(/myanmar/gi, 'Myanmar')
    .replace(/\b\w/g, c => c.toUpperCase())    // Title Case
    .trim();
}

function formatTimeLabel(label) {
  // Expecting: "Weekday | Morning (6–10 AM)"
  if (!label) return '-';
  return label.replace('|', '·');
}

// ---------- Input ----------
const data = $input.first().json;
const { meta, posts, pages, times, types } = data;

// ---------- Executive calculations ----------
const totalEngagement = pages.reduce((s, p) => s + (p.engagement || 0), 0);

// Sort pages by engagement descending
const sortedPages = pages
  .map(p => ({
    page: formatBrandName(p.page),
    posts: p.posts,
    reactions: p.reactions,
    comments: p.comments,
    shares: p.shares,
    engagement: p.engagement,
    percent: totalEngagement ? Math.round((p.engagement / totalEngagement) * 100) : 0
  }))
  .sort((a, b) => b.engagement - a.engagement);

// Top 5 detailed
const top5 = sortedPages.slice(0, 5);

// Remaining brands compact
const remaining = sortedPages.slice(5);

// Best content type & times
const bestType = types[0]?.type || '-';
const bestTimes = times.slice(0, 2).map(t => formatTimeLabel(t.bucket || t.label));

// ---------- Analyst table ----------
posts.sort((a, b) => b.timestamp - a.timestamp);

const rows = posts.map((p, i) => `
<tr style="background:${i % 2 === 0 ? '#fafafa' : '#ffffff'};">
  <td><b>${formatBrandName(p.page)}</b></td>
  <td style="text-align:center;">${p.type}</td>
  <td style="font-size:13px;line-height:1.4;">${p.content}</td>
  <td align="center">${p.reactions}</td>
  <td align="center">${p.comments}</td>
  <td align="center">${p.shares}</td>
  <td align="center" style="font-weight:bold;color:#d32f2f;">${p.engagement}</td>
  <td align="center">${p.reach}</td>
  <td style="font-size:12px;">${p.postedAt}</td>
  <td align="center"><a href="${p.link}">View</a></td>
</tr>
`).join('');

// ---------- HTML Email ----------
const html = `
<html>
<body style="font-family:Arial;background:#f4f6f8;">
<div style="max-width:1400px;margin:auto;background:#fff;padding:24px;">

<h2>📊 Executive Summary – Facebook Competitor Watch</h2>
<p style="font-size:13px;color:#666;">
Period: Last 7 Days · Timezone: ${meta.timezone}
</p>

<!-- Part 1: Top 5 Brands -->
<div style="background:#eef4ff;padding:16px;border-left:6px solid #1877f2;">
<h3>🏆 Top 5 Brands (Detailed)</h3>
<ol>
${top5.map((b, i) => `
<li>
<b>${b.page}</b> (Engagement: ${b.engagement}, ${b.percent}% of total)<br>
Posts: ${b.posts}, Reactions: ${b.reactions}, Comments: ${b.comments}, Shares: ${b.shares}
</li>
`).join('')}
</ol>
</div>

<!-- Part 2: Remaining Brands -->
${remaining.length ? `
<div style="background:#f4f8ff;padding:16px;border-left:6px solid #90caf9;margin-top:12px;">
<h3>📊 Other Brands</h3>
<ol start="6">
${remaining.map((b, i) => `
<li><b>${b.page}</b> – Engagement: ${b.engagement}, ${b.percent}% (${b.posts} posts)</li>
`).join('')}
</ol>
</div>` : ''}

<!-- Best Content & Times -->
<div style="background:#e8f5e9;padding:16px;border-left:6px solid #4caf50;margin-top:16px;">
<h3>📈 Insights</h3>
<ul>
<li><b>Most Effective Content Type:</b> ${bestType}</li>
<li><b>Highest Engagement Time Windows:</b>
<ol>
${bestTimes.map(t => `<li>${t}</li>`).join('')}
</ol>
</li>
</ul>
</div>

<!-- Recommended Actions -->
<div style="background:#f1f8e9;padding:16px;border-left:6px solid #4caf50;margin-top:16px;">
<h3>✅ Recommended Actions</h3>
<ol>
  <li>Prioritize <b>${bestType}</b> posts to maximize engagement</li>
  <li>Schedule primary campaigns during <b>${bestTimes[0]}</b></li>
  <li>Test secondary publishing during <b>${bestTimes[1]}</b></li>
</ol>
</div>

<hr style="margin:32px 0;">

<h2>📋 Detailed Post-Level Data</h2>
<table width="100%" cellpadding="8" cellspacing="0" border="1">
<thead style="background:#1a73e8;color:white;font-size:13px;">
<tr>
  <th>Page</th>
  <th>Type</th>
  <th>Content</th>
  <th>👍</th>
  <th>💬</th>
  <th>📢</th>
  <th>🔥 Engagement</th>
  <th>👁 Reach</th>
  <th>Posted</th>
  <th>Link</th>
</tr>
</thead>
<tbody>
${rows}
</tbody>
</table>

<p style="font-size:11px;color:#777;margin-top:12px;">
• Engagement = Reactions + Comments + Shares<br>
• Reach available only for video posts
</p>

</div>
</body>
</html>
`;

// ---------- Output ----------
return [
  {
    json: {
      subject: '📊 Myanmar ISP Facebook Performance: Weekly Comparative Analysis',
      emailBody: html,
    },
  },
];

// ===================================================
// TIKTOK ISP SPY — NORMALIZE + BRAND RESOLUTION v2
// ===================================================

const MMT_OFFSET_MS = 390 * 60 * 1000; // UTC+6:30

function toNumber(v) {
  const n = Number(v);
  return isNaN(n) ? 0 : n;
}

function normalizeKey(str) {
  if (!str) return "";
  return String(str).toLowerCase().replace(/[^a-z0-9]/g, "");
}

function getMMTHour(unixMs) {
  return new Date(unixMs + MMT_OFFSET_MS).getUTCHours();
}

function formatMMT(unixSec) {
  const d = new Date(unixSec * 1000 + MMT_OFFSET_MS);
  const day = String(d.getUTCDate()).padStart(2, "0");
  const months = ["Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov","Dec"];
  const mon = months[d.getUTCMonth()];
  const yr = d.getUTCFullYear();
  const hh = d.getUTCHours();
  const mm = String(d.getUTCMinutes()).padStart(2, "0");
  const ampm = hh >= 12 ? "PM" : "AM";
  const h12 = hh % 12 || 12;
  return `${day} ${mon} ${yr}, ${h12}:${mm} ${ampm} MMT`;
}

function timeBucket(mmtHour) {
  if (mmtHour >= 6  && mmtHour < 10) return "Morning (6–10 AM)";
  if (mmtHour >= 10 && mmtHour < 14) return "Midday (10 AM–2 PM)";
  if (mmtHour >= 14 && mmtHour < 18) return "Afternoon (2–6 PM)";
  if (mmtHour >= 18 && mmtHour < 22) return "Evening (6–10 PM)";
  return "Late Night (10 PM–6 AM)";
}

function detectTheme(text) {
  if (!text) return "General";
  const t = text.toLowerCase();

  // ISP Ecosystem logic (Order matters — more specific first)
  if (/promotion|discount|ဘေလ်|လျှော့စျေး|ဒေါင်း|အခမဲ့|free|gift|လက်ဆောင်/.test(t)) return "Promotions & Offers";
  if (/ဂိမ်း|game|pubg|mlbb|ping|pingကျ|stream|တိုက်ရိုက်|live/.test(t))            return "Gaming / Streaming";
  if (/လိုင်း|ကျပ်|နှေး|slow|disconnection|ပြတ်|လိုင်းကောင်း|wifiမရ|တိုင်/.test(t))     return "Network Quality / Support";
  if (/တပ်ဆင်|fiber|ftth|wifi|installation|အိမ်သုံး|router|စက်/.test(t))          return "Installation / B2C Plan";
  if (/မန့်|comment|mention|ရှိလား|\?|😁|humor|voiceeffect/.test(t))               return "Engagement / Humor";
  return "General";
}

// ----------------------------
// Brand Map — ISP Myanmar brands
// ----------------------------
const brandMap = {
  "u9myanmar":            "U9",
  "5bb_broadband":        "5BB",
  "atom_officialpage":    "ATOM",
  "fortunebroadband":     "Fortune",
  "myanmarnetinternet":   "Myanmar Net",
  "hiinternetwifi":       "Hi Internet",
  "user2309065208127":    "Kinetic",
  "mahar_net_yangon":     "Mahar Net",
  "margaglobaltele":      "Marga Global Telecom",
  "maxxbfiber_internet":  "MaxxB",
  "mbtwifi123":           "MBT",
  "mptofficialpage":      "MPT",
  "mmspeednet247":        "Myanmar Speed Net",
  "streamnet_fiber_yangon":"Stream Net",
  "truenetisp":           "TrueNet",
  "unilink_myanmar":      "Unilink",
  "welinkmyanmaryangon":  "Welink",
  "agbcommunication0":    "AGB Communication",
  "novalink22":           "Novalink"
};

// ----------------------------
// All monitored profiles (for inactive tracking)
// ----------------------------
const ALL_PROFILES = [
  "u9myanmar", "5bb_broadband", "atom_officialpage", "fortunebroadband",
  "myanmarnetinternet", "hiinternetwifi", "user2309065208127", "mahar_net_yangon",
  "margaglobaltele", "maxxbfiber_internet", "mbtwifi123", "mptofficialpage",
  "mmspeednet247", "streamnet_fiber_yangon", "truenetisp", "unilink_myanmar",
  "welinkmyanmaryangon", "agbcommunication0", "novalink22"
];

// ----------------------------
// Process raw data
// ----------------------------
const postsRaw = $input.first().json.data || [];
const posts = [];
const seenBrands = new Set();
const deadProfiles = [];

for (const data of postsRaw) {
  // Handle dead profiles (NOT_FOUND)
  if (data.error === "NOT_FOUND") {
    deadProfiles.push(data.input?.replace("@", "") || data.url);
    continue;
  }

  // Handle no-posts profiles — track brand but skip post
  if (data.note && data.note.includes("No videos")) {
    const profileName = normalizeKey(data?.authorMeta?.name || data.input || "");
    const brand = brandMap[profileName] || data?.authorMeta?.nickName || profileName;
    if (brand) seenBrands.add(brand);
    continue;
  }

  // Normal post
  const nameRaw = data?.authorMeta?.name || "";
  const nickRaw  = data?.authorMeta?.nickName || "";
  const nameKey  = normalizeKey(nameRaw);
  const nickKey  = normalizeKey(nickRaw);

  const brand = brandMap[nameKey] || brandMap[nickKey] || nickRaw || nameRaw;
  if (!brand || brand.trim() === "") continue;

  seenBrands.add(brand);

  const views    = toNumber(data.playCount);
  const likes    = toNumber(data.diggCount);
  const comments = toNumber(data.commentCount);
  const shares   = toNumber(data.shareCount);
  const saves    = toNumber(data.collectCount);
  const engagement = likes + comments + shares + saves;

  const unixMs   = data.createTime * 1000;
  const mmtHour  = getMMTHour(unixMs);

  let content = data.text || "-";
  if (content.length > 250) content = content.slice(0, 250) + "…";

  posts.push({
    brand_name:      brand,
    tiktok_handle:   nameRaw,
    content,
    theme:           detectTheme(data.text || ""),
    views,
    likes,
    comments,
    shares,
    saves,
    engagement,
    engagement_rate: views > 0 ? ((engagement / views) * 100).toFixed(2) + "%" : "0% ",
    postedAt:        formatMMT(data.createTime),
    timestamp:       unixMs,
    mmtHour,
    timeBucket:      timeBucket(mmtHour),
    dayType:         [0,6].includes(new Date(unixMs).getUTCDay()) ? "Weekend" : "Weekday",
    is_slideshow:    !!data.isSlideshow,
    video_duration:  toNumber(data?.videoMeta?.duration),
    effect_count:    (data.effectStickers || []).length,
    link:            `https://www.tiktok.com/@${nameRaw}/video/${data.id}`
  });
}

// Ensure all monitored profiles are counted in baseline seen status if not posting
ALL_PROFILES.forEach(p => {
  const brand = brandMap[p];
  if (brand) seenBrands.add(brand);
});

// ----------------------------
// Aggregate per brand
// ----------------------------
const statsMap = {};
for (const p of posts) {
  if (!statsMap[p.brand_name]) {
    statsMap[p.brand_name] = {
      brand_name: p.brand_name,
      post_count: 0, total_views: 0, total_likes: 0,
      total_comments: 0, total_shares: 0, total_saves: 0,
      total_engagement: 0, themes: {}
    };
  }
  const s = statsMap[p.brand_name];
  s.post_count++;
  s.total_views      += p.views;
  s.total_likes      += p.likes;
  s.total_comments   += p.comments;
  s.total_shares     += p.shares;
  s.total_saves      += p.saves;
  s.total_engagement += p.engagement;
  s.themes[p.theme]  = (s.themes[p.theme] || 0) + 1;
}

const summary = Object.values(statsMap).map(s => ({
  ...s,
  engagement_rate: s.total_views > 0
    ? ((s.total_engagement / s.total_views) * 100).toFixed(2) + "%"
    : "0%",
  dominant_theme: Object.entries(s.themes).sort((a,b) => b[1]-a[1])[0]?.[0] || "General"
}));

// Brands with profile but zero posts this week
const inactiveBrands = [...seenBrands]
  .filter(b => !statsMap[b])
  .map(b => ({ brand_name: b, reason: "No posts this week" }));

// Add dead profiles
deadProfiles.forEach(p => {
  const key = normalizeKey(p);
  const brand = brandMap[key] || p;
  inactiveBrands.push({ brand_name: brand, reason: "Profile not found (404)" });
});

return [{
  json: {
    generated_at: new Date().toISOString(),
    total_posts: posts.length,
    brands_detected: summary.length,
    posts,
    summary,
    inactive_brands: inactiveBrands
  }
}];

// ===================================================
// WEEKLY OBSERVATIONS GENERATOR (ISP EDITION)
// ===================================================

const { posts, summary, inactive_brands } = $input.first().json;

function safeNum(n) { return Number(n) || 0; }

// ── Top performer by engagement ──
const ranked = [...summary].sort((a,b) => safeNum(b.total_engagement) - safeNum(a.total_engagement));
const top = ranked[0];

// ── Best single post ──
const bestPost = [...posts].sort((a,b) => safeNum(b.engagement) - safeNum(a.engagement))[0];

// ── Most shares (Viral signal) ──
const mostShared = [...posts].sort((a,b) => safeNum(b.shares) - safeNum(a.shares))[0];

// ── Most comments (user feedback / discussion signal) ──
const mostCommented = [...posts].sort((a,b) => safeNum(b.comments) - safeNum(a.comments))[0];

// ── Peak posting time ──
const timeCounts = {};
posts.forEach(p => {
  timeCounts[p.timeBucket] = (timeCounts[p.timeBucket] || 0) + 1;
});
const peakTime = Object.entries(timeCounts).sort((a,b) => b[1]-a[1])[0];

// ── Weekend vs Weekday ──
const weekendPosts  = posts.filter(p => p.dayType === "Weekend").length;
const weekdayPosts  = posts.filter(p => p.dayType === "Weekday").length;

// ── Theme frequency across all posts ──
const themeCounts = {};
posts.forEach(p => {
  themeCounts[p.theme] = (themeCounts[p.theme] || 0) + 1;
});
const topTheme = Object.entries(themeCounts).sort((a,b) => b[1]-a[1])[0];

// ── Daily post distribution ──
const dayCounts = {};
posts.forEach(p => {
  const dayLabel = new Date(p.timestamp + 390*60*1000)
    .toLocaleDateString("en-GB", {timeZone: "UTC", weekday: "short", day:"2-digit", month:"short"});
  dayCounts[dayLabel] = (dayCounts[dayLabel] || 0) + 1;
});
