function toNumber(v) {
  const n = Number(v);
  return isNaN(n) ? 0 : n;
}

function resolveBrandName(post) {
  const candidates = [post.facebookUrl, post.inputUrl, post.url].filter(Boolean);
  for (const candidate of candidates) {
    const cleanUrl = candidate.toLowerCase();
    const match = BRAND_MAP.find(b => cleanUrl.includes(b.url.toLowerCase()));
    if (match) return match.brand;
  }
  return null;
}

function formatMyanmarDate(timeValue) {
  if (!timeValue) return null;
  const d = new Date(timeValue);
  if (isNaN(d)) return null;
  const date = new Intl.DateTimeFormat('en-GB', { timeZone: 'Asia/Yangon', day: '2-digit', month: 'short', year: 'numeric' }).format(d);
  const time = new Intl.DateTimeFormat('en-US', { timeZone: 'Asia/Yangon', hour: '2-digit', minute: '2-digit', hour12: true }).format(d);
  return `${date}, ${time}`;
}

function timeBucket(hour) {
  if (hour >= 6 && hour < 10) return 'Morning (6–10 AM)';
  if (hour >= 10 && hour < 14) return 'Midday (10 AM–2 PM)';
  if (hour >= 14 && hour < 18) return 'Afternoon (2–6 PM)';
  if (hour >= 18 && hour < 22) return 'Evening (6–10 PM)';
  return 'Late Night (10 PM–6 AM)';
}

function dayTypeFromTimestamp(ts) {
  const day = new Date(ts).getDay();
  return (day === 0 || day === 6) ? 'Weekend' : 'Weekday';
}

const items = $input.all();
let posts = [];
let droppedNoPosts = [];
let droppedUnknownBrand = [];

for (const item of items) {
  const data = Array.isArray(item.json?.data) ? item.json.data : [];
  for (const post of data) {
    try {
      if (post.error) { droppedNoPosts.push({ inputUrl: post.inputUrl, error: post.error }); continue; }
      const page = resolveBrandName(post);
      if (!page) { droppedUnknownBrand.push({ url: post.url, facebookUrl: post.facebookUrl }); continue; }
      const reactions = toNumber(post.likes);
      const comments = toNumber(post.comments);
      const shares = toNumber(post.shares);
      const engagement = reactions + comments + shares;
      if (!post.time) continue;
      const dateObj = new Date(post.time);
      if (isNaN(dateObj)) continue;
      const hour = dateObj.getHours();
      const bucket = timeBucket(hour);
      const dayType = dayTypeFromTimestamp(dateObj.getTime());
      let type = 'Text';
      if (post.isVideo) type = 'Video';
      else if (Array.isArray(post.media) && post.media.length > 0) type = 'Image';
      let reach = '–';
      if (post.isVideo) { reach = post.viewsCount ? toNumber(post.viewsCount) : 'Video (no data)'; }
      let content = post.text || '-';
      if (content.length > 250) content = content.slice(0, 250) + '...';
      posts.push({ page, type, content, reactions, comments, shares, engagement, reach, postedAt: formatMyanmarDate(post.time), timestamp: dateObj.getTime(), hour, timeBucket: bucket, dayType, link: post.url || '#' });
    } catch (e) { continue; }
  }
}

const allBrandNames = BRAND_MAP.map(b => b.brand);
const postedBrands = new Set(posts.map(p => p.page));
const silentBrands = allBrandNames
