    const noPostEntry = droppedNoPosts.find(d => BRAND_MAP.find(bm => bm.brand === b && d.inputUrl && d.inputUrl.toLowerCase().includes(bm.url.toLowerCase())));
    return { brand: b, reason: noPostEntry ? 'No posts found (private or empty in last 7 days)' : 'No posts this week' };
  });

const pageSummary = {};
for (const p of posts) {
  if (!pageSummary[p.page]) { pageSummary[p.page] = { page: p.page, posts: 0, reactions: 0, comments: 0, shares: 0, engagement: 0 }; }
  pageSummary[p.page].posts += 1;
  pageSummary[p.page].reactions += p.reactions;
  pageSummary[p.page].comments += p.comments;
  pageSummary[p.page].shares += p.shares;
  pageSummary[p.page].engagement += p.engagement;
}

// ----------------------------
// FIX: rank content type & time windows by AVERAGE engagement per post,
// not total engagement. Total engagement rewards whichever type/time is
// simply used MOST OFTEN, not whichever actually performs best.
// A minimum sample size guard prevents a single lucky post from
// crowning a rarely-used slot as "best".
// ----------------------------
const MIN_SAMPLE_SIZE = 2;

const timeSummary = {};
for (const p of posts) {
  const key = `${p.dayType} | ${p.timeBucket}`;
  if (!timeSummary[key]) { timeSummary[key] = { label: key, posts: 0, engagement: 0 }; }
  timeSummary[key].posts++;
  timeSummary[key].engagement += p.engagement;
}

const typeSummary = {};
for (const p of posts) {
  if (!typeSummary[p.type]) { typeSummary[p.type] = { type: p.type, posts: 0, engagement: 0 }; }
  typeSummary[p.type].posts++;
  typeSummary[p.type].engagement += p.engagement;
}

function rankBySampleAwareAvg(list) {
  return list
    .map(item => ({ ...item, avgEngagement: item.posts ? Math.round(item.engagement / item.posts) : 0, qualified: item.posts >= MIN_SAMPLE_SIZE }))
    .sort((a, b) => {
      if (a.qualified !== b.qualified) return a.qualified ? -1 : 1;
      return b.avgEngagement - a.avgEngagement;
    });
}

const pages = Object.values(pageSummary).sort((a, b) => b.engagement - a.engagement);
const times = rankBySampleAwareAvg(Object.values(timeSummary));
const types = rankBySampleAwareAvg(Object.values(typeSummary));

return [
